108	        if (!isEmpty(datasourceConfiguration.getProperties())) {
109	            boolean isSendSessionEnabled = false;
110	            String secretKey = null;
111	
112	            for (Property property : datasourceConfiguration.getProperties()) {
113	                if (IS_SEND_SESSION_ENABLED_KEY.equals(property.getKey())) {
