134	    public void setHeaderFromAutoGeneratedHeaders(ActionConfiguration actionConfiguration) {
135	        if (isEmpty(actionConfiguration.getAutoGeneratedHeaders())) {
136	            return;
137	        }
138	
139	        if (isEmpty(actionConfiguration.getHeaders())) {
140	            actionConfiguration.setHeaders(actionConfiguration.getAutoGeneratedHeaders());
141	            return;
142	        }
143	
144	        Set<String> userAddedHeaderKeys = actionConfiguration.getHeaders().stream()
145	                .filter(header -> !StringUtils.isEmpty(header.getKey()))
146	                .map(Property::getKey)
147	                .map(String::toLowerCase) // Header keys are case-insensitive
148	                .collect(Collectors.toSet());
149	
150	        actionConfiguration.getAutoGeneratedHeaders().stream()
151	                .filter(header -> !StringUtils.isEmpty(header.getKey()))
152	                .forEach(header -> {
153	                    /**
154	                     * Header keys are case insensitive:
155	                     * https://stackoverflow.com/questions/5258977/are-http-headers-case-sensitive
156	                     */
157	                    if (!userAddedHeaderKeys.contains(header.getKey().toLowerCase())) {
158	                        actionConfiguration.getHeaders().add(header);
159	                    }
160	                });
